-- EraLens period import: minguo
-- Window: 1912-01 .. 2026-09
BEGIN;

-- cleanup
-- remove stale auto-generated 史料缺 (元首空缺期应留白)
DELETE FROM reigns WHERE dynasty_id IN ('roc') AND person_id = 'system-missing-ruler';
DELETE FROM relations WHERE id = 'rel-jiang-jieshi-jiang-jieshi-succession';
DELETE FROM event_dynasties WHERE event_id = 'puyi-leaves-forbidden-city';

-- persons
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yuan-shikai', '袁世凯', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['政治家','军事家'], '袁世凯出身淮军系统，晚清历任要职并参与新军建设。辛亥革命后接任临时大总统，1913年正式就任；其政府镇压二次革命、解散国民党，1915年称帝引发护国战争，次年取消帝制并去世，北洋政府权力随之分散。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/袁世凯"}]'::jsonb, NULL, NULL, '大总统')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('li-yuanhong', '黎元洪', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['政治家'], '黎元洪原为湖北新军将领，武昌起义后被推为湖北军政府都督。袁世凯死后他先后两度任大总统，任内与段祺瑞围绕参战、国会及内阁权力发生府院之争；第二任期在直皖冲突后结束。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/黎元洪"}]'::jsonb, NULL, NULL, '大总统')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('feng-guozhang', '冯国璋', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['军事家','政治家'], '冯国璋为北洋将领、直系重要人物，曾任副总统。黎元洪离职后，他以副总统代理大总统，并于1917—1918年任总统；其任内南北对立与护法战争持续，卸任后仍参与北洋政局。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冯国璋"}]'::jsonb, NULL, NULL, '代理大总统')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('xu-shichang', '徐世昌', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['政治家'], '徐世昌是清末翰林出身的北洋政治人物，与袁世凯关系密切。1918年当选大总统，主张停战与“偃武修文”，但南北分裂、军阀割据未能消弭；1922年直系控制北京后辞职。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/徐世昌"}]'::jsonb, NULL, NULL, '大总统')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('cao-kun', '曹锟', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['军事家','政治家'], '曹锟是北洋直系军阀首领，曾任直隶督军。1923年通过贿选当选大总统，任内颁行《中华民国宪法》；1924年冯玉祥发动北京政变，曹锟被囚并辞职，北洋政府陷入新一轮权力重组。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹锟"}]'::jsonb, NULL, NULL, '大总统')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('zhang-zuolin', '张作霖', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['军事家','政治家'], '张作霖出身东北地方武装，逐步控制奉天并建立奉系，成为北洋后期重要军政领袖。1927年就任陆海军大元帅并在北京行使最高权力；北伐军推进后撤离北京，1928年在皇姑屯遭日军炸车身亡。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张作霖"}]'::jsonb, NULL, NULL, '陆海军大元帅')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('lin-sen', '林森', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['政治家'], '林森是辛亥革命元老，曾任国民政府委员长（主席）。1931—1943年任主席期间，实际军政决策主要由蒋介石等人掌握；抗日战争期间长期留重庆办公，1943年去世。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/林森"}]'::jsonb, NULL, NULL, '国民政府主席')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('jiang-jieshi', '蒋介石', ARRAY['蒋中正'], NULL, NULL, 1887, 10, 1975, 4, ARRAY['军事家','政治家'], '蒋介石是国民革命军主要领导人，曾任黄埔军校校长并主持北伐。1928年后多次担任南京国民政府主席，抗日战争期间任军事与政府领导职务，1948年当选行宪后首任总统；1949年中央政府迁台后继续执政，1975年去世。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蒋介石"}]'::jsonb, NULL, NULL, '')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('li-zongren', '李宗仁', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['军事家','政治家'], '李宗仁是桂系将领，抗战期间指挥台儿庄战役，后当选副总统。蒋介石于1949年引退后，他依法代理总统；蒋介石于1950年复行视事，李宗仁随后离开大陆并长期旅居海外。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李宗仁"}]'::jsonb, NULL, NULL, '代总统')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('tan-yankai', '谭延闿', ARRAY['谭延闓'], NULL, NULL, 1880, 1, 1930, 9, ARRAY['政治家'], '谭延闿是湖南地方政治人物、国民党元老，曾任湖南督军及国民政府要职。宁汉合流后于1928年出任南京国民政府主席，张作霖离京后成为该包所记的主线元首；随后转任行政院院长。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/谭延闿"}]'::jsonb, NULL, NULL, '国民政府主席')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yan-jiagan', '严家淦', ARRAY[]::text[], NULL, NULL, 1905, 10, 1993, 12, ARRAY['政治家'], '严家淦是财政与行政官员，曾任台湾省政府主席、行政院院长及副总统。蒋介石于1975年去世后，他继任总统至1978年；任内支持行政院推动十大建设，并筹设新竹科学工业园区。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/严家淦"}]'::jsonb, NULL, NULL, '领导人')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('jiang-jingguo', '蒋经国', ARRAY[]::text[], NULL, NULL, 1910, 4, 1988, 1, ARRAY['政治家'], '蒋经国长期参与国民党与政府事务，曾任行政院院长，1978年继任总统。其任内推动十大建设、扩大本地人才参与，并于1987年宣布解除戒严、开放党禁报禁及赴大陆探亲；1988年去世，由李登辉继任。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蒋经国"}]'::jsonb, NULL, NULL, '')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('li-denghui', '李登辉', ARRAY[]::text[], NULL, NULL, 1923, 1, 2020, 7, ARRAY['政治家'], '李登辉原任副总统，蒋经国去世后继任总统，并于1990年当选。任内推动终止动员戡乱时期、国会全面改选与总统直选，1996年成为首次全民直选产生的总统；2000年政党轮替后卸任。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李登辉"}]'::jsonb, NULL, NULL, '')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('chen-shuibian', '陈水扁', ARRAY[]::text[], NULL, NULL, 1950, 10, NULL, NULL, ARRAY['政治家'], '陈水扁曾任台北市长，2000年当选总统，结束国民党长期执政并实现首次和平政党轮替。其两届任内推动“小三通”、社会与司法改革，台湾于2002年加入世界贸易组织；2008年卸任。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈水扁"}]'::jsonb, NULL, NULL, '')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('ma-yingjiu', '马英九', ARRAY[]::text[], NULL, NULL, 1950, 7, NULL, NULL, ARRAY['政治家'], '马英九曾任法务部长、台北市长及国民党主席，2008年当选总统，成为政党轮替后的第二位总统。任内与大陆恢复制度化协商并推动直航、签署《两岸经济合作架构协议》，同时推动地方行政区调整；2016年卸任。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/马英九"}]'::jsonb, NULL, NULL, '')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('cai-yingwen', '蔡英文', ARRAY[]::text[], NULL, NULL, 1956, 8, NULL, NULL, ARRAY['政治家'], '蔡英文是法律与两岸事务学者，曾任行政院副院长及民进党主席，2016年当选总统，成为首位女性国家元首。任内推动年金改革、能源转型与国防政策调整，并签署同性婚姻法案；2020年连任，2024年卸任。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蔡英文"}]'::jsonb, NULL, NULL, '')
