INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('lai-qingde', '赖清德', ARRAY[]::text[], NULL, NULL, 1959, 10, NULL, NULL, ARRAY['政治家'], '赖清德曾任立法委员、台南市长、行政院院长及副总统，2024年当选并就任中华民国总统。其任期延续于蔡英文之后，面对两岸关系、能源与产业转型等议题。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赖清德"}]'::jsonb, NULL, NULL, '')
