INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('duan-qirui', '段祺瑞', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['军事家','政治家'], '段祺瑞是北洋皖系首领，袁世凯时期多次任国务总理。1924年北京政变后出任临时执政，试图召开善后会议、重组政局；其政府在国民会议争议及奉系、直系压力下失势，1926年下台。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段祺瑞"}]'::jsonb, NULL, NULL, '临时执政')
