INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('zhou-ziqi', '周自齐', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['政治家'], '周自齐为北洋政府官员，曾任国务总理。黎元洪辞职后，他于1922年短暂以国务院名义摄行大总统职权，直至黎元洪复任；此段反映当时总统职位与内阁更迭的频繁。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周自齐"}]'::jsonb, NULL, NULL, '国务院摄行')
