INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('gao-lingwei', '高凌霨', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['政治家'], '高凌霨是北洋政府官员，曾任直隶省长、国务总理。黎元洪第二次离职后，他于1923年短暂以国务院名义摄行大总统职权，随后曹锟就任总统。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/高凌霨"}]'::jsonb, NULL, NULL, '国务院摄行')
