INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('huang-fu', '黄郛', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['政治家'], '黄郛为国民党政治人物，曾任外交总长等职。1924年北京政变后，他短暂以国务院名义摄行大总统职权，并参与迎段祺瑞出任临时执政；此后转入南京国民政府任职。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/黄郛"}]'::jsonb, NULL, NULL, '国务院摄行')
