INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('hu-weide', '胡惟德', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['外交家','政治家'], '胡惟德是资深外交官与北洋政府官员，曾任国务总理。段祺瑞下台后，他两度以国务院名义摄行元首职权，分别处于1926年临时执政交接及1927年政府改组期间。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/胡惟德"}]'::jsonb, NULL, NULL, '国务院摄行')
