INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yan-huiqing', '颜惠庆', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['外交家','政治家'], '颜惠庆是外交官、曾任国务总理。1926年段祺瑞离职后，他主持摄政内阁并以国务院名义短暂摄行大总统职权；奉系与国民军争夺北京政权期间，政府权力迅速更替。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/颜惠庆"}]'::jsonb, NULL, NULL, '国务院摄行')
