INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('du-xigui', '杜锡珪', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['军事家','政治家'], '杜锡珪为海军将领，曾任海军总长和国务总理。1926年颜惠庆内阁解散后，他短暂代理国务总理并以国务院名义摄行大总统职权，随后将权力交由顾维钧内阁。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杜锡珪"}]'::jsonb, NULL, NULL, '国务院摄行')
