VALUES ('gu-weijun', '顾维钧', ARRAY['V. K. Wellington Koo'], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['外交家','政治家'], '顾维钧是外交家，因巴黎和会拒绝在《凡尔赛条约》上签字而知名，后任国务总理兼外交总长。1926—1927年他主持内阁并以国务院名义摄行大总统职权，安国军政府成立后结束该段职务。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/顾维钧"}]'::jsonb, NULL, NULL, '国务院摄行')
